    {
      "id": "E2f5405a9df5b8c11",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Tecnologias inline de separação podem incorporar ciclones e eletrocoalescedores para elevar a eficiência de separação entre fases e também remover areia da corrente produzida, com objetivo de evitar corrosão dos equipamentos de produção e processamento primário.",
          "trechos": [
            "E2f5405a9df5b8c11:0:698"
          ],
          "condicoes": [
            "quando esses dispositivos são instalados no interior de linhas inline",
            "no contexto de separação de líquido em gás, gás em líquido, óleo e água, e remoção de areia"
          ],
          "limites": [
            "o texto descreve funções e objetivos tecnológicos, sem apresentar critérios quantitativos de seleção ou desempenho",
            "não aborda diretamente equalização ou despressurização de linhas"
          ]
        },
        {
          "proposicao": "O emprego dessas tecnologias é associado à redução de espaço requerido para a planta de processamento e ou ao aumento da capacidade de produção e processamento da unidade.",
          "trechos": [
            "E2f5405a9df5b8c11:698:1396"
          ],
          "condicoes": [
            "por meio do uso de tecnologias inline e compactas em substituição a arranjos tradicionais"
          ],
          "limites": [
            "trata de benefício esperado de arquitetura de processo",
            "não demonstra consequência universal para todos os campos ou instalações"
          ]
        },
        {
          "proposicao": "A instalação dessas tecnologias no solo marítimo é apresentada como possibilidade para aumentar capacidade de produção e ou reduzir o número de unidades flutuantes, além de diminuir o volume de água oleosa tratado e descartado offshore quando houver reinjeção da água separada.",
          "trechos": [
            "E2f5405a9df5b8c11:1396:2090"
          ],
          "condicoes": [
            "na hipótese de instalação subsea dessas tecnologias",
            "quando a água oleosa separada for reinjetada em reservatório"
          ],
          "limites": [
            "o texto usa linguagem prospectiva, não requisito ou resultado comprovado geral",
            "não trata diretamente de perda de contenção, interfaces de emergência ou barreiras de poço"
          ]
        }
      ]
    },
    {
      "id": "E174f5fc054d428ce",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "A ISO TS de integridade de poço na fase operacional é descrita como adotando abordagem integrada de gestão da integridade, incluindo análise de riscos, identificação de barreiras de contenção ao fluxo indesejado e identificação de elementos críticos das barreiras.",
          "trechos": [
            "E174f5fc054d428ce:0:700"
          ],
          "condicoes": [
            "no contexto da fase operacional do poço",
            "segundo a descrição do texto sobre a especificação técnica ISO TS"
          ],
          "limites": [
            "trata-se de norma internacional mencionada no texto, não conversão automática em requisito brasileiro",
            "o trecho não detalha metodologia de verificação de cada barreira"
          ]
        },
        {
          "proposicao": "Segundo o texto, a mesma especificação prevê que o operador defina padrões de desempenho dos componentes do poço e limites de operação dos equipamentos, além de exigir monitoramento de pressão anular e gestão de falhas de integridade com testes e perfis.",
          "trechos": [
            "E174f5fc054d428ce:700:1399"
          ],
          "condicoes": [
            "na aplicação da especificação técnica citada",
            "para componentes do poço e equipamentos na fase operacional"
          ],
          "limites": [
            "os índices aceitáveis de vazamento são citados apenas como exemplo, sem valores no trecho",
            "não há parâmetros numéricos nem frequência de monitoramento aplicáveis a todos os casos"
          ]
        },
        {
          "proposicao": "O trecho cita monitoramento contínuo e registro de pressão anular bradenhead durante operações de estimulação, incluindo monitoramento adicional entre revestimentos intermediário e de produção quando existir revestimento intermediário.",
          "trechos": [
            "E174f5fc054d428ce:1399:2099",
            "E174f5fc054d428ce:2099:2361"
          ],
          "condicoes": [
            "durante operações de estimulação",
            "havendo revestimento intermediário no poço"
          ],
          "limites": [
            "o próprio trecho vincula essa exigência ao contexto de estimulação, não à operação submarina geral em FPSO",
            "estimulação se aproxima mais de operação de poço específica e não cobre linhas, risers ou interfaces topside em geral"
          ]
        }
      ]
    }
  ],
